def copy_first_weight(apps, schema_editor):
    """Move M2M `weights` to the new `weight` FK: each product keeps its smallest weight.

    If another product in the same family+flavor already took that weight, the product
    is left without a weight so the unique variant constraint can be applied safely.
    """
    Product = apps.get_model("catalog", "Product")
    taken = set()
    for product in Product.objects.order_by("sort_order", "id").prefetch_related("weights"):
        weights = sorted(product.weights.all(), key=lambda w: (w.unit, w.value))
        if not weights:
            continue
        weight = weights[0]
        key = (product.family_id, product.flavor_id, weight.id)
        if product.family_id is not None:
            if key in taken:
                continue
            taken.add(key)
        product.weight = weight
        product.save(update_fields=["weight"])


